"use strict";(self.webpackChunkhn_cho_sh=self.webpackChunkhn_cho_sh||[]).push([[94041],{3331:(e,s,i)=>{i.d(s,{R:()=>a,x:()=>l});var t=i(36672);const n={},r=t.createContext(n);function a(e){const s=t.useContext(r);return t.useMemo((function(){return"function"==typeof e?e(s):{...s,...e}}),[s,e])}function l(e){let s;return s=e.disableParentContext?"function"==typeof e.components?e.components(n):e.components||n:a(e.components),t.createElement(r.Provider,{value:s},e.children)}},16496:(e,s,i)=>{i.r(s),i.d(s,{assets:()=>o,contentTitle:()=>l,default:()=>c,frontMatter:()=>a,metadata:()=>t,toc:()=>u});const t=JSON.parse('{"id":"2023/04/14","title":"2023-04-14","description":"Arrestation dans l\'assassinat de Bob Lee \xe0 SF - le tueur pr\xe9sum\xe9 travaillait \xe9galement dans le secteur de la technologie","source":"@site/i18n/fr/docusaurus-plugin-content-docs/current/2023/04/14.md","sourceDirName":"2023/04","slug":"/2023/04/14","permalink":"/fr/2023/04/14","draft":false,"unlisted":false,"editUrl":"https://github.com/anaclumos/heimdall/blob/main/i18n/fr/docusaurus-plugin-content-docs//current/2023/04/14.md","tags":[],"version":"current","frontMatter":{"localized_date":"14 avril 2023","top_news":"Arrestation dans l\'assassinat de Bob Lee \xe0 SF - le tueur pr\xe9sum\xe9 travaillait \xe9galement dans le secteur de la technologie"},"sidebar":"defaultSidebar","previous":{"title":"2023-04-15","permalink":"/fr/2023/04/15"},"next":{"title":"2023-04-13","permalink":"/fr/2023/04/13"}}');var n=i(23420),r=i(3331);const a={localized_date:"14 avril 2023",top_news:"Arrestation dans l'assassinat de Bob Lee \xe0 SF - le tueur pr\xe9sum\xe9 travaillait \xe9galement dans le secteur de la technologie"},l="2023-04-14",o={},u=[{value:"Arrestation dans l&#39;assassinat de Bob Lee \xe0 SF - le tueur pr\xe9sum\xe9 travaillait \xe9galement dans le secteur de la technologie",id:"arrestation-dans-lassassinat-de-bob-lee-\xe0-sf---le-tueur-pr\xe9sum\xe9-travaillait-\xe9galement-dans-le-secteur-de-la-technologie",level:2},{value:"L&#39;interdiction de l&#39;h\xe9bergement YouTube-DL ouvre la voie \xe0 une censure privatis\xe9e",id:"linterdiction-de-lh\xe9bergement-youtube-dl-ouvre-la-voie-\xe0-une-censure-privatis\xe9e",level:2},{value:"L&#39;art de l&#39;ing\xe9nierie automobile",id:"lart-de-ling\xe9nierie-automobile",level:2},{value:"Apple utilisera 100 % de cobalt recycl\xe9 dans ses batteries d&#39;ici 2025",id:"apple-utilisera-100--de-cobalt-recycl\xe9-dans-ses-batteries-dici-2025",level:2},{value:"Nous avons multipli\xe9 par 6 la vitesse de d\xe9marrage de Podman.",id:"nous-avons-multipli\xe9-par-6-la-vitesse-de-d\xe9marrage-de-podman",level:2},{value:"Am\xe9liorer Tailscale gr\xe2ce \xe0 l&#39;open source d&#39;Apple",id:"am\xe9liorer-tailscale-gr\xe2ce-\xe0-lopen-source-dapple",level:2},{value:"Dessins anim\xe9s",id:"dessins-anim\xe9s",level:2},{value:"Amazon CodeWhisperer, gratuit pour une utilisation individuelle, est d\xe9sormais disponible en g\xe9n\xe9ral",id:"amazon-codewhisperer-gratuit-pour-une-utilisation-individuelle-est-d\xe9sormais-disponible-en-g\xe9n\xe9ral",level:2},{value:"Google a d\xe9j\xe0 retir\xe9 six produits en 2023",id:"google-a-d\xe9j\xe0-retir\xe9-six-produits-en-2023",level:2},{value:"Nvidia RTX Remix Runtime Open Source disponible d\xe8s maintenant",id:"nvidia-rtx-remix-runtime-open-source-disponible-d\xe8s-maintenant",level:2}];function d(e){const s={a:"a",h1:"h1",h2:"h2",header:"header",p:"p",...(0,r.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(s.header,{children:(0,n.jsx)(s.h1,{id:"2023-04-14",children:"2023-04-14"})}),"\n",(0,n.jsx)(s.h2,{id:"arrestation-dans-lassassinat-de-bob-lee-\xe0-sf---le-tueur-pr\xe9sum\xe9-travaillait-\xe9galement-dans-le-secteur-de-la-technologie",children:"Arrestation dans l'assassinat de Bob Lee \xe0 SF - le tueur pr\xe9sum\xe9 travaillait \xe9galement dans le secteur de la technologie"}),"\n",(0,n.jsxs)(s.p,{children:["(",(0,n.jsx)(s.a,{href:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/",children:"https://missionlocal.org/2023/04/bob-lee-killing-arrest-made-san-francisco/"}),").\nUne arrestation a eu lieu dans le cadre de l'assassinat de Bob Lee, cadre dans le secteur de la technologie, et le tueur pr\xe9sum\xe9 travaillait \xe9galement dans le secteur de la technologie et \xe9tait connu de Lee. La police aurait trouv\xe9 Lee et le suspect conduisant ensemble dans une voiture enregistr\xe9e au nom du suspect, et affirme qu'une sorte de confrontation a eu lieu \xe0 bord du v\xe9hicule et qu'elle s'est peut-\xeatre poursuivie apr\xe8s le d\xe9part de Lee. La couverture de la mort de Lee a \xe9t\xe9 regroup\xe9e avec d'autres malheurs et crimes r\xe9cents de San Francisco, bien que cela ne repr\xe9sente pas exactement l'exp\xe9rience v\xe9cue par la plupart des San-Franciscains."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35555525",children:"Discussion Service"}),".\nLe meurtre d'un cadre du secteur technologique \xe0 San Francisco a suscit\xe9 des discussions sur les facteurs tels que le sans-abrisme, la sant\xe9 mentale, la toxicomanie et la pauvret\xe9 qui ont pu conduire au crime, mais les commentateurs mettent en garde contre les g\xe9n\xe9ralisations. Le d\xe9bat porte \xe9galement sur l'utilisation des statistiques par rapport aux anecdotes personnelles lors de l'\xe9valuation des taux de criminalit\xe9, ainsi que sur la n\xe9cessit\xe9 d'une approche communautaire pour traiter les probl\xe8mes complexes des sans-abri, de la toxicomanie et de la criminalit\xe9. Les utilisateurs soulignent l'importance d'\xe9valuer les niveaux de criminalit\xe9 en fonction de la pauvret\xe9 plut\xf4t que de comparer diff\xe9rentes cultures et de ne pas tirer de conclusions h\xe2tives \xe0 partir d'un seul cas."]}),"\n",(0,n.jsx)(s.h2,{id:"linterdiction-de-lh\xe9bergement-youtube-dl-ouvre-la-voie-\xe0-une-censure-privatis\xe9e",children:"L'interdiction de l'h\xe9bergement YouTube-DL ouvre la voie \xe0 une censure privatis\xe9e"}),"\n",(0,n.jsxs)(s.p,{children:["(Original) (",(0,n.jsx)(s.a,{href:"https://torrentfreak.com/youtube-dl-hosting-ban-paves-the-way-to-privatized-censorship-230411/",children:"https://torrentfreak.com/youtube-dl-hosting-ban-paves-the-way-to-privatized-censorship-230411/"}),").\nUn tribunal allemand a jug\xe9 qu'Uberspace \xe9tait responsable de l'h\xe9bergement du site web de youtube-dl - un outil open-source qui permet de t\xe9l\xe9charger le contenu de YouTube. Uberspace avertit que le verdict pourrait conduire \xe0 une censure privatis\xe9e et fait appel de la d\xe9cision, bien que le tribunal ait estim\xe9 qu'Uberspace \"peut \xeatre tenu responsable pour avoir dout\xe9 de la validit\xe9 d'une demande de retrait\", m\xeame s'il n'\xe9tait pas clair que l'outil violait la loi."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35553337",children:"Discussion Service"}),".\nL'interdiction de l'h\xe9bergement de YouTube-DL est consid\xe9r\xe9e comme une avanc\xe9e vers une censure privatis\xe9e, la RIAA et la MPAA privil\xe9giant l'argent et le pouvoir \xe0 la d\xe9cence. Le r\xf4le de la propri\xe9t\xe9 intellectuelle dans la limitation du flux d'informations est d\xe9battu, avec une s\xe9rie de points de vue, y compris la limitation de la port\xe9e et de la dur\xe9e. Les utilisateurs proposent des alternatives et d\xe9noncent la d\xe9pendance \xe0 l'\xe9gard de GitHub, tout en discutant de la d\xe9centralisation et des probl\xe8mes de s\xe9curit\xe9 par obscurit\xe9 dans la protection contre la copie."]}),"\n",(0,n.jsx)(s.h2,{id:"lart-de-ling\xe9nierie-automobile",children:"L'art de l'ing\xe9nierie automobile"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://www.howacarworks.com/video-course",children:"Original"}),".\nL'art de l'ing\xe9nierie automobile est un cours vid\xe9o complet compos\xe9 de plus de 122 le\xe7ons avec 20 heures d'images expliquant chaque partie d'une voiture dans les moindres d\xe9tails, couvrant les bases de l'ing\xe9nierie automobile jusqu'\xe0 son niveau le plus avanc\xe9. Le cours est accompagn\xe9 d'un manuel de 200 pages et est disponible en ligne ou dans les applications iOS et Android pour un paiement unique de 25 $ avec un acc\xe8s \xe0 vie, et est film\xe9 professionnellement en qualit\xe9 4K avec des sous-titres complets. Le cours est salu\xe9 par les t\xe9l\xe9spectateurs pour son enseignement captivant et son excellente valeur de production."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35552393",children:"Discussion Service"}),".\nLes utilisateurs de Hacker News partagent leurs exp\xe9riences et recommandent des ressources pour apprendre l'ing\xe9nierie automobile, y compris des cours vid\xe9o interactifs et des mod\xe8les de voitures sp\xe9cifiques. Les commentateurs discutent des avantages de la compr\xe9hension de la m\xe9canique automobile, des limites de la d\xe9pendance \xe0 l'\xe9gard de l'intelligence artificielle et donnent des conseils sur les r\xe9parations de voitures \xe0 faire soi-m\xeame. En outre, les utilisateurs d\xe9battent de l'utilit\xe9 des cours et des outils payants, et certains critiquent l'apparition sur le site de publicit\xe9s pour des cours payants."]}),"\n",(0,n.jsx)(s.h2,{id:"apple-utilisera-100--de-cobalt-recycl\xe9-dans-ses-batteries-dici-2025",children:"Apple utilisera 100 % de cobalt recycl\xe9 dans ses batteries d'ici 2025"}),"\n",(0,n.jsxs)(s.p,{children:["(",(0,n.jsx)(s.a,{href:"https://www.apple.com/newsroom/2023/04/apple-will-use-100-percent-recycled-cobalt-in-batteries-by-2025/",children:"https://www.apple.com/newsroom/2023/04/apple-will-use-100-percent-recycled-cobalt-in-batteries-by-2025/"}),").\nApple a annonc\xe9 son intention d'utiliser 100 % de cobalt recycl\xe9 dans toutes ses batteries d'ici 2025, ainsi que des \xe9l\xe9ments de terres rares enti\xe8rement recycl\xe9s pour les aimants et 100 % d'\xe9tain recycl\xe9 pour les cartes de circuits imprim\xe9s. L'objectif d'Apple est de n'utiliser que des mat\xe9riaux recycl\xe9s et renouvelables et la soci\xe9t\xe9 s'approvisionne d\xe9j\xe0 \xe0 plus de 95 % en tungst\xe8ne, \xe0 pr\xe8s de trois quarts en terres rares et \xe0 plus de deux tiers en aluminium \xe0 partir de mat\xe9riaux recycl\xe9s \xe0 100 %. Apple utilise la r\xe9alit\xe9 augment\xe9e (RA) pour guider le d\xe9montage des appareils pour les partenaires de recyclage et augmenter la r\xe9cup\xe9ration des terres rares, entra\xeenant ainsi un changement \xe0 l'\xe9chelle de l'industrie pour r\xe9duire la d\xe9pendance \xe0 l'\xe9gard des min\xe9raux nouvellement extraits."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35554270",children:"Discussion Service"}),".\nApple a annonc\xe9 son intention d'utiliser 100 % de cobalt recycl\xe9 dans ses batteries d'ici \xe0 2025 et de r\xe9duire les d\xe9chets plastiques, mais les utilisateurs s'interrogent sur l'efficacit\xe9 de ces changements et se demandent si l'entreprise doit rendre publique sa technologie de recyclage. Le d\xe9bat sur les batteries rempla\xe7ables par l'utilisateur se poursuit, avec des arguments selon lesquels elles sont n\xe9fastes pour l'environnement, tandis que d'autres sugg\xe8rent que les m\xe9thodes de recyclage et l'allongement de la dur\xe9e de vie des produits peuvent r\xe9soudre ce probl\xe8me. L'engagement d'Apple en faveur des mat\xe9riaux recyclables et d'une cha\xeene d'approvisionnement neutre en carbone est salu\xe9, mais critiqu\xe9 pour sa conception et sa cha\xeene d'approvisionnement en cobalt. Les utilisateurs discutent de la dur\xe9e de vie des iPhones et des t\xe9l\xe9phones Android, ainsi que des m\xe9thodes de recyclage des batteries. Certains utilisateurs sugg\xe8rent d'utiliser des batteries MagSafe comme batterie principale pour les iPhones, tandis que d'autres remettent en question leur efficacit\xe9."]}),"\n",(0,n.jsx)(s.h2,{id:"nous-avons-multipli\xe9-par-6-la-vitesse-de-d\xe9marrage-de-podman",children:"Nous avons multipli\xe9 par 6 la vitesse de d\xe9marrage de Podman."}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://www.redhat.com/sysadmin/speed-containers-podman-raspberry-pi",children:"Original"}),".\nLe moteur de conteneurs de Red Hat, Podman, a multipli\xe9 par six sa vitesse de d\xe9marrage en supprimant les processus inutiles et en rem\xe9diant aux inefficacit\xe9s mineures qui ont un impact sur les applications critiques telles que les voitures, pour lesquelles un d\xe9marrage des conteneurs en temps quasi r\xe9el est essentiel. L'\xe9quipe a utilis\xe9 le stockage transitoire et a fourni des solutions de contournement pour les probl\xe8mes du noyau, ce qui a permis d'acc\xe9l\xe9rer le d\xe9marrage des conteneurs. L'utilisation de l'option --transient-store est id\xe9ale pour les p\xe9riph\xe9riques, bien que les conteneurs en mode mixte ne soient pas pris en charge."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35551830",children:"Discussion Service"}),".\nPodman de Red Hat constate une multiplication par six de la vitesse de d\xe9marrage des voitures, bien que les utilisateurs de Discussion Service discutent de la surcomplication des voitures modernes et soul\xe8vent des inqui\xe9tudes quant \xe0 la fiabilit\xe9 et \xe0 la maintenance. La discussion s'oriente vers des d\xe9bats sur le droit \xe0 la r\xe9paration, l'utilisation de microservices et de conteneurs, et l'\xe9quilibre entre les avanc\xe9es technologiques et l'aspect pratique."]}),"\n",(0,n.jsx)(s.h2,{id:"am\xe9liorer-tailscale-gr\xe2ce-\xe0-lopen-source-dapple",children:"Am\xe9liorer Tailscale gr\xe2ce \xe0 l'open source d'Apple"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://tailscale.dev/blog/darwin-spelunking",children:"Original"}),".\nL'\xe9quipe Tailscale a utilis\xe9 l'open source d'Apple pour d\xe9boguer les bogues li\xe9s \xe0 l'interface r\xe9seau pour leur version 1.36, en s'appuyant sur ifconfig pour d\xe9terminer l'interface r\xe9seau active. Lorsque Tailscale est configur\xe9 pour utiliser un n\u0153ud de sortie, celui-ci devient la route par d\xe9faut, ce qui n\xe9cessite un correctif pour \"lier\" syst\xe9matiquement les requ\xeates r\xe9seau \xe0 l'interface r\xe9seau active sans causer de trafic en boucle. SIOCGIFDELEGATE, disponible via ioctl, permet d'obtenir l'interface physique sous-jacente et a \xe9t\xe9 impl\xe9ment\xe9 dans le code de Tailscale pour macOS et iOS."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35559124",children:"Discussion Service"}),".\nLes utilisateurs de Discussion Service discutent des avantages et des d\xe9fis des logiciels \xe0 source ouverte et ferm\xe9e dans l'am\xe9lioration de Tailscale via la source ouverte d'Apple. Certains clients payants donnent la priorit\xe9 \xe0 la r\xe9putation du produit de base open source de Tailscale, tandis que d'autres soul\xe8vent des probl\xe8mes sp\xe9cifiques avec Tailscale, tels que la difficult\xe9 d'acc\xe9der aux partages de r\xe9seau sur Windows 11 et l'\xe9puisement potentiel de la batterie sur les appareils iOS. La discussion met en \xe9vidence l'importance de prendre en compte diff\xe9rentes perspectives et le fait que Tailscale gagne du terrain sur Zerotier en raison de son syst\xe8me de maillage et du d\xe9ploiement continu de nouvelles fonctionnalit\xe9s, mais certains utilisateurs du produit sont pr\xe9occup\xe9s par les questions de revenus et de foss\xe9."]}),"\n",(0,n.jsx)(s.h2,{id:"dessins-anim\xe9s",children:"Dessins anim\xe9s"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://fairanimateddrawings.com/site/home",children:"Original"}),".\nLe d\xe9p\xf4t \"Animated Drawings\" sur Github met en \u0153uvre l'algorithme d\xe9crit dans l'article \"A Method for Automatically Animating Children's Drawings of the Human Figure\", permettant aux utilisateurs de cr\xe9er des animations personnalis\xe9es avec leurs propres personnages dessin\xe9s \xe0 la main. Le processus d'installation est simple et les fichiers de configuration peuvent \xeatre modifi\xe9s pour changer diverses options, notamment les formats de sortie et les images d'arri\xe8re-plan. Le r\xe9f\xe9rentiel fournit \xe9galement des scripts et des mod\xe8les pour animer des dessins personnels, et une d\xe9mo bas\xe9e sur un navigateur est disponible pour une utilisation rapide et facile."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35561203",children:"Discussion Service"}),".\nLe projet Fair Animated Drawings anime des dessins \xe0 l'aide d'un code, disponible dans une version bas\xe9e sur un navigateur et sur GitHub. Les utilisateurs s'int\xe9ressent \xe0 son potentiel pour les id\xe9es commerciales et esp\xe8rent une version d'application Android. Un travail pertinent sur l'estimation de pose non photor\xe9aliste appel\xe9 Gesture3D semble applicable \xe0 un cas d'utilisation sp\xe9cifique, et les candidatures pour YC Summer 2023 sont ouvertes."]}),"\n",(0,n.jsx)(s.h2,{id:"amazon-codewhisperer-gratuit-pour-une-utilisation-individuelle-est-d\xe9sormais-disponible-en-g\xe9n\xe9ral",children:"Amazon CodeWhisperer, gratuit pour une utilisation individuelle, est d\xe9sormais disponible en g\xe9n\xe9ral"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://aws.amazon.com/blogs/aws/amazon-codewhisperer-free-for-individual-use-is-now-generally-available/",children:"Original"}),".\nAmazon CodeWhisperer, un compagnon de codage IA en temps r\xe9el, est d\xe9sormais disponible de mani\xe8re g\xe9n\xe9rale et comprend un niveau CodeWhisperer Individual qui est gratuit pour tous les d\xe9veloppeurs. L'outil aide les d\xe9veloppeurs \xe0 \xe9crire du code rapidement et en toute s\xe9curit\xe9, sans quitter leur IDE. CodeWhisperer propose des suggestions pour des cas d'utilisation g\xe9n\xe9raux dans une vari\xe9t\xe9 de langages et peut filtrer ou signaler les suggestions de code qui peuvent ressembler \xe0 des donn\xe9es d'entra\xeenement open-source particuli\xe8res, contribuant ainsi \xe0 r\xe9duire le risque d'utiliser un code potentiellement biais\xe9 ou d\xe9fectueux."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35554460",children:"Discussion Service"}),".\nAmazon CodeWhisperer est d\xe9sormais disponible de mani\xe8re g\xe9n\xe9rale et prend en charge plusieurs langages, notamment Python, Java, JavaScript, TypeScript et C#. Bien que Copilot soit apparemment meilleur que CodeWhisperer, ce dernier est un outil utile qui pourrait faire en sorte que le code g\xe9n\xe9r\xe9 par l'IA devienne la norme. En outre, Amazon a lanc\xe9 CodeGuru Reviewer, un outil d'IA qui analyse le code afin d'identifier les probl\xe8mes et de recommander des correctifs \xe0 des fins d'efficacit\xe9 et de r\xe9duction des co\xfbts."]}),"\n",(0,n.jsx)(s.h2,{id:"google-a-d\xe9j\xe0-retir\xe9-six-produits-en-2023",children:"Google a d\xe9j\xe0 retir\xe9 six produits en 2023"}),"\n",(0,n.jsxs)(s.p,{children:["(",(0,n.jsx)(s.a,{href:"https://toolhub.tech/blog/Google-2023-Shutdown-Spree-6-Products-Pulled-in-Just-4-Months/",children:"https://toolhub.tech/blog/Google-2023-Shutdown-Spree-6-Products-Pulled-in-Just-4-Months/"}),").\nGoogle a ferm\xe9 six produits au cours des quatre premiers mois de 2023, notamment le concours de programmation Code Jam, la plateforme de m\xe9dias sociaux Google Currents, l'application Street View, la technologie vestimentaire Google Jacquard, le service de jeux en nuage Google Stadia et le routeur sans fil Google OnHub. Bien que certains de ces produits datent de plus de dix ans, Google a \xe9t\xe9 critiqu\xe9 pour son habitude de mettre fin brutalement \xe0 des services populaires."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35553421",children:"Discussion Service"}),".\nGoogle a abandonn\xe9 six produits en 2023, avec des pr\xe9occupations concernant la transparence et l'\xe9tiquetage des produits, ainsi que le manque de soutien pour les entreprises qui ont \xe9chou\xe9, notamment Google Glass et Google Plus. Alors que l'unit\xe9 \"cloud\" se d\xe9veloppe avec une part de march\xe9 de 10 %, des inqui\xe9tudes sont soulev\xe9es quant \xe0 l'engagement des clients et des d\xe9veloppeurs et \xe0 l'algorithme de destruction des comptes. Les utilisateurs d\xe9battent des solutions et des co\xfbts pour am\xe9liorer la pr\xe9cision de ChatGPT, tandis que la r\xe9putation de Google en mati\xe8re d'abandon de projets suscite des critiques sur le support produit pour les consommateurs."]}),"\n",(0,n.jsx)(s.h2,{id:"nvidia-rtx-remix-runtime-open-source-disponible-d\xe8s-maintenant",children:"Nvidia RTX Remix Runtime Open Source disponible d\xe8s maintenant"}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"https://www.nvidia.com/en-us/geforce/news/rtx-remix-runtime-open-source-download/",children:"Original"}),".\nNvidia a publi\xe9 le runtime RTX Remix, une plateforme de modding open source pour remasteriser les jeux classiques DirectX 8 et 9 avec le path tracing, des textures am\xe9lior\xe9es par l'IA et des ressources cr\xe9\xe9es par l'utilisateur. La bo\xeete \xe0 outils du cr\xe9ateur RTX Remix permet aux moddeurs d'assigner de nouveaux \xe9l\xe9ments et lumi\xe8res dans une sc\xe8ne remast\xe9ris\xe9e, et d'utiliser des outils d'IA pour reconstruire l'apparence de n'importe quel \xe9l\xe9ment. Le runtime RTX Remix, quant \xe0 lui, capture une sc\xe8ne de jeu, remplace les objets \xe0 la lecture et injecte la technologie RTX, telle que le tra\xe7age de chemin, DLSS 3 et Reflex, dans le jeu."]}),"\n",(0,n.jsxs)(s.p,{children:[(0,n.jsx)(s.a,{href:"http://news.ycombinator.com/item?id=35552378",children:"Discussion Service"}),".\nNvidia a publi\xe9 son RTX Remix Runtime open-source permettant aux utilisateurs de jouer \xe0 des jeux plus anciens avec le ray tracing en temps r\xe9el, bien que tous les jeux ne fonctionnent pas. Les utilisateurs de Hacker News discutent de l'importance des pilotes open-source par rapport aux pilotes propri\xe9taires, de la r\xe9putation de Nvidia et des performances m\xe9diocres de RTX sur le mat\xe9riel non-Nvidia. Les utilisateurs sp\xe9culent \xe9galement sur un favoritisme potentiel et sugg\xe8rent de soutenir les d\xe9veloppeurs de crypto-monnaies qui mettent en \u0153uvre des syst\xe8mes de preuve de travail bas\xe9s uniquement sur le GPU. Un utilisateur note le d\xe9veloppement par Remedy de remakes de jeux Max Payne sur PC utilisant Remix et discute des probl\xe8mes de frame pacing et de stuttering de la technologie."]})]})}function c(e={}){const{wrapper:s}={...(0,r.R)(),...e.components};return s?(0,n.jsx)(s,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}}}]);